fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of rows in the input
    let rows = x.len();
    // Number of columns in the input (assumed non-empty and rectangular)
    let cols = x[0].len();

    // Create a vector of `cols` empty rows, each with capacity `rows`
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for _ in 0..cols {
        result.push(Vec::with_capacity(rows));
    }

    // Fill the transposed matrix
    for row in x {
        for (j, &val) in row.iter().enumerate() {
            result[j].push(val);
        }
    }

    result
}

